"use client"

import { type CSSProperties } from "react"
import { LineBadge } from "@/components/tfl/brand/line-badge"
import {
  DISRUPTION_LEADING_CLASS,
  StatusDisruptionBlock,
} from "@/components/tfl/status/status-disruption-copy"
import { useUnattendedSequence } from "@/hooks/use-unattended-sequence"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { partitionStatusBoardLines } from "@/lib/tfl/status-board"
import {
  buildStatusDisplayFrames,
  visibleHeadingChips,
  type StatusDetailScope,
  type StatusDisplayFrame,
} from "@/lib/tfl/status-display"
import type { StatusLine } from "@/lib/tfl/status-types"
import type { PrepareLineAnnouncementsOptions } from "@/lib/tfl/status-reason"
import { UNATTENDED_DEFAULT_DWELL_MS } from "@/lib/tfl/unattended-sequence"
import { cn } from "@/lib/utils"

export type { StatusLine } from "@/lib/tfl/status-types"
export type { StatusDetailScope }

const BOARD_RHYTHM_VARS = {
  "--arrivals-unit": "0.5rem",
  "--arrivals-row": "calc(var(--arrivals-unit) * 6)",
} as CSSProperties

const TILE_CLASS =
  "box-border h-[var(--arrivals-row)] min-h-[var(--arrivals-row)] max-h-[var(--arrivals-row)] shrink-0 overflow-clip"

export type TubeStatusDisplayProps = {
  data?: readonly StatusLine[]
  tiles?: number
  detailScope?: StatusDetailScope
  detailLineIds?: readonly string[]
  now?: number
  currentOnly?: boolean
  dedupe?: boolean
  rawReason?: boolean
  dwellMs?: number
  startDelayMs?: number
  className?: string
  error?: string | null
}

const ChipDwellBar = ({
  filling,
  paused,
  frameKey,
  dwellMs,
}: {
  filling: boolean
  paused: boolean
  frameKey: string
  dwellMs: number
}) => (
  <div className="h-1 w-full overflow-hidden bg-foreground/15" aria-hidden>
    {filling ? (
      <div
        key={`${frameKey}-go`}
        className="tfl-unattended-dwell h-full w-full bg-foreground/50"
        data-paused={paused ? "true" : undefined}
        style={{ "--unattended-dwell": `${dwellMs}ms` } as CSSProperties}
      />
    ) : null}
  </div>
)

const HeadingChips = ({
  lineIds,
  activeLineId,
  dwellMs,
  frameKey,
  paused,
  started,
  canAdvance,
}: {
  lineIds: readonly string[]
  activeLineId?: string
  dwellMs: number
  frameKey: string
  paused: boolean
  started: boolean
  canAdvance: boolean
}) => {
  const visible = visibleHeadingChips(lineIds, activeLineId)
  if (visible.length === 0) return null
  return (
    <div className="flex min-w-0 shrink-0 items-end gap-1" aria-hidden>
      {visible.map((id) => {
        const isActive = id === activeLineId
        return (
          <div key={id} className="flex min-w-0 flex-col leading-none">
            <LineBadge
              lineId={id}
              className={cn(
                "h-5 justify-center px-1.5",
                activeLineId && !isActive && "opacity-40"
              )}
            />
            <ChipDwellBar
              filling={isActive && canAdvance && started}
              paused={paused}
              frameKey={frameKey}
              dwellMs={dwellMs}
            />
          </div>
        )
      })}
    </div>
  )
}

const StatusDisplayFrameView = ({
  frame,
  tiles,
  dwellMs,
  started,
  paused,
  canAdvance,
  frameKey,
}: {
  frame: StatusDisplayFrame
  tiles: number
  dwellMs: number
  started: boolean
  paused: boolean
  canAdvance: boolean
  frameKey: string
}) => {
  const expand = tiles <= 0
  const bodyTiles = expand ? 1 : Math.max(0, tiles - 1)
  const announcementTile = frame.tiles.find(
    (tile) => tile.kind === "announcements"
  )
  const chipsTile = frame.tiles.find((tile) => tile.kind === "chips")
  const showHeadingChips = frame.headingLineIds.length > 0
  const activeLineId = frame.activeLineId
  const namedHeading =
    frame.headingLineIds.length === 0 && Boolean(activeLineId)
  const pageIndex = frame.pageIndex ?? 0
  const pageCount = frame.pageCount ?? 1

  return (
    <div
      className="flex w-full flex-col"
      aria-label={`${frame.heading}${
        frame.activeLineName ? `, ${frame.activeLineName}` : ""
      }${pageCount > 1 ? `, page ${pageIndex + 1} of ${pageCount}` : ""}`}
    >
      <div
        data-line={namedHeading ? activeLineId : undefined}
        className={cn(
          "relative flex items-center text-xl leading-7 font-semibold",
          TILE_CLASS
        )}
      >
        <p
          className={cn(
            "m-0 min-w-0 flex-1 truncate",
            showHeadingChips && "pr-2",
            namedHeading && "tfl-dark-line-text text-[var(--line-color)]"
          )}
        >
          {frame.heading}
        </p>
        {showHeadingChips ? (
          <HeadingChips
            lineIds={frame.headingLineIds}
            activeLineId={activeLineId}
            dwellMs={dwellMs}
            frameKey={frameKey}
            paused={paused}
            started={started}
            canAdvance={canAdvance}
          />
        ) : null}
      </div>
      {bodyTiles > 0 ? (
        <div
          className={cn(
            "relative",
            !expand && "overflow-clip",
            announcementTile && "bg-muted"
          )}
          style={
            expand
              ? undefined
              : {
                  height: `calc(var(--arrivals-row) * ${bodyTiles})`,
                }
          }
        >
          {announcementTile && announcementTile.kind === "announcements" ? (
            <div className="py-[calc(var(--arrivals-row)/4)]">
              <StatusDisruptionBlock
                announcements={announcementTile.items}
                quiet={announcementTile.quiet}
              />
            </div>
          ) : null}
          {chipsTile && chipsTile.kind === "chips" ? (
            <div className="flex min-h-0 flex-col">
              {frame.bodyHeading ? (
                <p
                  className={cn(
                    "m-0 flex items-center text-xl leading-7 font-semibold",
                    TILE_CLASS
                  )}
                >
                  {frame.bodyHeading}
                </p>
              ) : null}
              <div className="ml-auto flex w-full max-w-lg flex-wrap justify-end gap-1">
                {chipsTile.lineIds.map((id) => (
                  <LineBadge
                    key={id}
                    lineId={id}
                    className="h-5 justify-center px-1.5"
                  />
                ))}
              </div>
            </div>
          ) : null}
          {frame.otherGoodServiceCopy ? (
            <p
              className={cn(
                "m-0 text-sm text-muted-foreground",
                DISRUPTION_LEADING_CLASS
              )}
            >
              {frame.otherGoodServiceCopy}
            </p>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

export const TubeStatusDisplaySkeleton = ({
  tiles = 4,
}: {
  tiles?: number
}) => (
  <div
    className="flex w-full flex-col saturate-0"
    style={BOARD_RHYTHM_VARS}
    aria-busy
    aria-label="Loading line status"
  >
    <div
      className={cn(
        "flex items-center text-xl leading-7 font-semibold text-muted-foreground",
        TILE_CLASS
      )}
    >
      Status
    </div>
    {Array.from({ length: Math.max(0, tiles - 1) }, (_, index) => (
      <div key={index} className={TILE_CLASS} />
    ))}
  </div>
)

export const TubeStatusDisplay = ({
  data,
  tiles = 4,
  detailScope = "network",
  detailLineIds,
  now,
  currentOnly = true,
  dedupe = true,
  rawReason,
  dwellMs = UNATTENDED_DEFAULT_DWELL_MS,
  startDelayMs = 0,
  className,
  error = null,
}: TubeStatusDisplayProps) => {
  const reducedMotion = usePrefersReducedMotion()
  const prepareOptions: PrepareLineAnnouncementsOptions = {
    now,
    currentOnly,
    dedupe,
    rawReason,
  }
  const sections = partitionStatusBoardLines(data ?? [], prepareOptions)
  const frames = buildStatusDisplayFrames(sections, {
    tiles,
    detailScope,
    detailLineIds,
  })
  const itemIds = frames.map((frame) => frame.id)
  const sequence = useUnattendedSequence({
    itemIds,
    dwellMs,
    startDelayMs,
    enabled: itemIds.length > 1,
  })
  const frame = frames[sequence.index] ?? frames[0]
  const heightClass = "flex w-full flex-col"

  const expand = tiles <= 0
  const lockedHeight = expand
    ? undefined
    : `calc(var(--arrivals-row) * ${tiles})`
  const fillerTiles = expand ? 0 : Math.max(0, tiles - 1)

  if (error) {
    return (
      <div
        className={cn(heightClass, className)}
        style={{
          ...BOARD_RHYTHM_VARS,
          minHeight: lockedHeight,
        }}
        role="alert"
      >
        <p
          className={cn(
            "flex items-center text-base text-destructive",
            TILE_CLASS
          )}
        >
          {error}
        </p>
        {Array.from({ length: fillerTiles }, (_, index) => (
          <div key={index} className={TILE_CLASS} aria-hidden />
        ))}
      </div>
    )
  }

  if (!frame) {
    return (
      <div
        className={cn(heightClass, className)}
        style={{
          ...BOARD_RHYTHM_VARS,
          minHeight: lockedHeight,
        }}
        role="status"
      >
        <p
          className={cn("flex items-center text-muted-foreground", TILE_CLASS)}
        >
          No status
        </p>
        {Array.from({ length: fillerTiles }, (_, index) => (
          <div key={index} className={TILE_CLASS} aria-hidden />
        ))}
      </div>
    )
  }

  return (
    <div
      className={cn(heightClass, className)}
      style={{
        ...BOARD_RHYTHM_VARS,
        minHeight: lockedHeight,
      }}
      onFocus={sequence.handleFocus}
      onBlur={sequence.handleBlur}
    >
      <div
        key={frame.id}
        className={cn(!reducedMotion && "transition-opacity duration-200")}
      >
        <StatusDisplayFrameView
          frame={frame}
          tiles={tiles}
          dwellMs={dwellMs}
          started={sequence.started}
          paused={sequence.pauseReasons.length > 0}
          canAdvance={itemIds.length > 1}
          frameKey={frame.id}
        />
      </div>
    </div>
  )
}

import { QuietChip } from "@/components/tfl/arrivals/quiet-chip"
import { cn } from "@/lib/utils"

export type StatusDisruptionCopyItem = {
  text: string
  statusSeverityDescription?: string
}

/** Half-tile leading — each wrapped line is exactly `--arrivals-row / 2`. */
export const DISRUPTION_LEADING_CLASS = "leading-[calc(var(--arrivals-row)/2)]"

const DISRUPTION_COPY_CLASS = cn(
  "text-base text-pretty text-foreground/80",
  DISRUPTION_LEADING_CLASS
)

/** `align-top` keeps the 20px chip inside the half-tile line box. */
const SeverityChip = ({ label }: { label: string }) => (
  <QuietChip className="mr-[0.35em] align-top">
    {label}
  </QuietChip>
)

export const StatusDisruptionCopy = ({
  announcement,
  quiet = false,
}: {
  announcement: StatusDisruptionCopyItem
  quiet?: boolean
}) => {
  const severityLabel = announcement.statusSeverityDescription?.trim()
  const body = announcement.text
  const bodyIsOnlyLabel = severityLabel
    ? body.toLowerCase() === severityLabel.toLowerCase()
    : false

  return (
    <p
      className={cn(
        "m-0",
        DISRUPTION_COPY_CLASS,
        quiet && "text-muted-foreground"
      )}
    >
      {severityLabel ? <SeverityChip label={severityLabel} /> : null}
      {bodyIsOnlyLabel ? null : body}
    </p>
  )
}

export const StatusDisruptionBlock = ({
  announcements,
  quiet = false,
}: {
  announcements: readonly StatusDisruptionCopyItem[]
  quiet?: boolean
}) => (
  <div className={DISRUPTION_LEADING_CLASS}>
    {announcements.map((announcement, index) => (
      <StatusDisruptionCopy
        key={index}
        announcement={announcement}
        quiet={quiet}
      />
    ))}
  </div>
)

import type { HTMLAttributes, ReactNode } from "react"
import {
  ARRIVALS_RANK_CHIP_WIDTH_CLASS,
  CHIP_CAP_TEXT_BOX_CLASS,
  arrivalsOrdinalSuffix,
} from "@/components/tfl/arrivals/chip-text"
import { cn } from "@/lib/utils"

export type QuietChipProps = HTMLAttributes<HTMLSpanElement> & {
  children: ReactNode
}

/** Quiet neutral chip used for status severity labels and arrival ranks. */
export const QuietChip = ({
  children,
  className,
  ...props
}: QuietChipProps) => (
  <span
    {...props}
    className={cn(
      "inline-flex h-5 max-w-full shrink-0 items-center justify-center overflow-hidden bg-foreground/5 px-1.5 align-middle text-xs font-semibold text-foreground/60",
      className
    )}
  >
    <span className={CHIP_CAP_TEXT_BOX_CLASS}>{children}</span>
  </span>
)

/**
 * Chip then arrivals-owned sentence as siblings. Never stitch the label
 * into the sentence string.
 */
export const ArrivalsStatusSentence = ({
  chip,
  sentence,
}: {
  chip?: string | null
  sentence: string
}) => (
  <>
    {chip ? (
      <QuietChip className="mr-[0.35em] shrink-0">{chip}</QuietChip>
    ) : null}
    {sentence}
  </>
)

/**
 * Unattended list position. Fixed `3ch`. Suffix uses OpenType `ordn` when
 * the face has it, with a raised fallback so `st`/`nd`/`rd`/`th` still sit
 * as superscripts.
 */
export const ArrivalRankChip = ({
  rank,
  className,
  ...props
}: { rank: number } & Omit<QuietChipProps, "children">) => (
  <QuietChip
    aria-hidden
    className={cn(
      ARRIVALS_RANK_CHIP_WIDTH_CLASS,
      "px-0 tabular-nums",
      className
    )}
    {...props}
  >
    {rank}
    <sup className="top-0 font-features-['ordn'] text-[0.62em] leading-none ordinal">
      {arrivalsOrdinalSuffix(rank)}
    </sup>
  </QuietChip>
)

import { splitTextFrames } from "@/lib/tfl/unattended-sequence"
import type {
  StatusBoardLine,
  StatusBoardSections,
} from "@/lib/tfl/status-board"
import type { LineAnnouncement } from "@/lib/tfl/status-reason"

export type StatusDisplayPhase = "disruptions" | "good-service"
export type StatusDetailScope = "network" | "selection" | "none"

export type StatusDisplayAnnouncement = Pick<
  LineAnnouncement,
  "text" | "statusSeverityDescription"
>

export type StatusDisplayTile =
  | {
      kind: "announcements"
      items: readonly StatusDisplayAnnouncement[]
      quiet?: boolean
    }
  | { kind: "chips"; lineIds: readonly string[] }
  | { kind: "empty" }

export type StatusDisplayFrame = {
  id: string
  phase: StatusDisplayPhase
  heading: string
  headingLineIds: readonly string[]
  bodyHeading?: string
  activeLineId?: string
  activeLineName?: string
  activeModeName?: string
  otherGoodServiceCopy?: string
  pageIndex?: number
  pageCount?: number
  tiles: readonly StatusDisplayTile[]
}

export type StatusDisplayOptions = {
  tiles: number
  detailScope?: StatusDetailScope
  detailLineIds?: readonly string[]
  charsPerTile?: number
}

export type StatusStripAllocation = {
  showDisruptedSummary: boolean
  showOtherSummary: boolean
  reasonUnits: number
}

const DEFAULT_CHARS_PER_TILE = 200
const LINES_PER_TILE = 2

const lineId = (row: StatusBoardLine): string =>
  row.line.id?.trim() || row.line.name?.trim() || "unknown"

const lineName = (row: StatusBoardLine): string =>
  row.line.name?.trim() || lineId(row)

const filterBySelection = (
  rows: readonly StatusBoardLine[],
  detailLineIds: readonly string[] | undefined
): StatusBoardLine[] => {
  if (!detailLineIds?.length) return [...rows]
  const wanted = new Set(detailLineIds)
  return rows.filter((row) => wanted.has(lineId(row)))
}

const toDisplayAnnouncements = (
  announcement: LineAnnouncement
): StatusDisplayAnnouncement[] => {
  const paragraphs = announcement.text
    .split(/\n+/)
    .map((part) => part.trim())
    .filter(Boolean)
  const source = paragraphs.length > 0 ? paragraphs : [announcement.text]
  return source.map((text, index) => ({
    text,
    statusSeverityDescription:
      index === 0 ? announcement.statusSeverityDescription : undefined,
  }))
}

const announcementBody = (item: StatusDisplayAnnouncement): string => {
  const label = item.statusSeverityDescription?.trim()
  const body = item.text.trim()
  if (label && body.toLowerCase() === label.toLowerCase()) return ""
  return body
}

const estimateAnnouncementLines = (
  item: StatusDisplayAnnouncement,
  charsPerLine: number
): number => {
  const label = item.statusSeverityDescription?.trim()
  const reserved = label ? label.length + 1 : 0
  const chars = reserved + announcementBody(item).length
  if (chars <= 0) return label ? 1 : 0
  return Math.max(1, Math.ceil(chars / Math.max(1, charsPerLine)))
}

const splitAnnouncement = (
  item: StatusDisplayAnnouncement,
  pageChars: number
): StatusDisplayAnnouncement[] => {
  const body = announcementBody(item)
  if (!body) return [item]
  const chunks = splitTextFrames(body, pageChars)
  if (chunks.length <= 1) return [item]
  return chunks.map((chunk, index) => ({
    text: chunk,
    statusSeverityDescription:
      index === 0 ? item.statusSeverityDescription : undefined,
  }))
}

/**
 * Stack every chip+copy block on one page when each block fits on its own.
 * Only split a single block that is longer than the body by itself.
 */
export const packAnnouncementPages = (
  items: readonly StatusDisplayAnnouncement[],
  options: { linesPerPage: number; charsPerLine: number }
): StatusDisplayAnnouncement[][] => {
  if (items.length === 0) return []
  const linesPerPage = Math.max(1, options.linesPerPage)
  const charsPerLine = Math.max(1, options.charsPerLine)
  const pageChars = linesPerPage * charsPerLine
  const fitsAlone = (item: StatusDisplayAnnouncement) =>
    estimateAnnouncementLines(item, charsPerLine) <= linesPerPage

  if (items.every(fitsAlone)) return [[...items]]

  const pages: StatusDisplayAnnouncement[][] = []
  let current: StatusDisplayAnnouncement[] = []
  let used = 0

  const flush = () => {
    if (current.length === 0) return
    pages.push(current)
    current = []
    used = 0
  }

  for (const item of items) {
    const lines = estimateAnnouncementLines(item, charsPerLine)
    if (!fitsAlone(item)) {
      flush()
      for (const piece of splitAnnouncement(item, pageChars)) {
        pages.push([piece])
      }
      continue
    }
    if (current.length > 0 && used + lines > linesPerPage) {
      flush()
    }
    current.push(item)
    used += lines
  }
  flush()
  return pages.length > 0 ? pages : [[...items]]
}

export const statusDisplayReasonText = (
  tiles: readonly StatusDisplayTile[]
): string =>
  tiles
    .flatMap((tile) => {
      if (tile.kind !== "announcements") return []
      return tile.items.map(
        (item) =>
          announcementBody(item) ||
          item.statusSeverityDescription?.trim() ||
          item.text.trim()
      )
    })
    .filter(Boolean)
    .join(" ")

const framesForLine = (
  row: StatusBoardLine,
  options: {
    phase: StatusDisplayPhase
    heading: string
    headingLineIds: readonly string[]
    bodyTiles: number
    charsPerTile: number
    otherGoodServiceCopy?: string
  }
): StatusDisplayFrame[] => {
  const id = lineId(row)
  const items = row.announcements.flatMap(toDisplayAnnouncements)
  const bodyTiles = options.bodyTiles
  const identity = {
    activeLineId: id,
    activeLineName: lineName(row),
    activeModeName: row.line.modeName,
  }
  const quiet = row.kind === "closed"

  if (bodyTiles <= 0) {
    return [
      {
        id: `${options.phase}:${id}:summary`,
        phase: options.phase,
        heading: options.heading,
        headingLineIds: options.headingLineIds,
        ...identity,
        otherGoodServiceCopy: options.otherGoodServiceCopy,
        pageIndex: 0,
        pageCount: 1,
        tiles: [],
      },
    ]
  }

  const pages = packAnnouncementPages(items, {
    linesPerPage: bodyTiles * LINES_PER_TILE,
    charsPerLine: Math.max(
      1,
      Math.round(options.charsPerTile / LINES_PER_TILE)
    ),
  })
  const source = pages.length > 0 ? pages : [[]]

  return source.map((pageItems, index) => ({
    id: `${options.phase}:${id}:${index}`,
    phase: options.phase,
    heading: options.heading,
    headingLineIds: options.headingLineIds,
    ...identity,
    otherGoodServiceCopy:
      index === source.length - 1 ? options.otherGoodServiceCopy : undefined,
    pageIndex: index,
    pageCount: source.length,
    tiles:
      pageItems.length > 0
        ? [{ kind: "announcements" as const, items: pageItems, quiet }]
        : [],
  }))
}

const goodServiceBodyFrames = (
  rows: readonly StatusBoardLine[],
  options: {
    disruptionLineIds: readonly string[]
    bodyTiles: number
    otherGoodServiceCopy?: string
  }
): StatusDisplayFrame[] => {
  if (rows.length === 0) return []
  const lineIds = rows.map(lineId)
  const keepDisruptions = options.disruptionLineIds.length > 0
  return [
    {
      id: `good-service:${lineIds.join(",")}`,
      phase: "good-service",
      heading: keepDisruptions ? "Service disruptions" : "Good service",
      headingLineIds: keepDisruptions ? options.disruptionLineIds : [],
      bodyHeading: keepDisruptions ? "Good service" : undefined,
      otherGoodServiceCopy: options.otherGoodServiceCopy,
      pageIndex: 0,
      pageCount: 1,
      tiles: options.bodyTiles > 0 ? [{ kind: "chips", lineIds }] : [],
    },
  ]
}

/**
 * Turn partitioned status sections into a fixed-height unattended sequence.
 * One tile is summary-only. N tiles = heading + N - 1 content tiles.
 * 0 expands: no height cap, all copy on one page.
 */
export const buildStatusDisplayFrames = (
  sections: StatusBoardSections,
  options: StatusDisplayOptions
): StatusDisplayFrame[] => {
  const expand = options.tiles <= 0
  const scope = options.detailScope ?? "network"
  const charsPerTile = options.charsPerTile ?? DEFAULT_CHARS_PER_TILE
  const bodyTiles = expand
    ? Number.POSITIVE_INFINITY
    : Math.max(1, Math.floor(options.tiles)) - 1
  const detailIds = options.detailLineIds
  const wanted = new Set(detailIds ?? [])

  const disruptionSummary =
    scope === "selection"
      ? filterBySelection(sections.disruptions, detailIds)
      : sections.disruptions
  const disruptionDetail = filterBySelection(sections.disruptions, detailIds)
  const goodDetail =
    scope === "selection"
      ? filterBySelection(sections.goodService, detailIds)
      : sections.goodService

  const priorityHeadingIds =
    scope === "none" ? [] : disruptionDetail.map(lineId)
  const otherHeadingIds =
    scope === "none"
      ? []
      : disruptionSummary
          .map(lineId)
          .filter((id) => !priorityHeadingIds.includes(id))
  const disruptionHeadingIds =
    scope === "none" ? [] : [...priorityHeadingIds, ...otherHeadingIds]

  const disruptionFrames = disruptionDetail.flatMap((row) =>
    framesForLine(row, {
      phase: "disruptions",
      heading: scope === "none" ? lineName(row) : "Service disruptions",
      headingLineIds: disruptionHeadingIds,
      bodyTiles,
      charsPerTile,
    })
  )

  const otherDisruptionRows =
    scope === "network" && wanted.size > 0
      ? sections.disruptions.filter((row) => !wanted.has(lineId(row)))
      : []
  const otherDisruptionFrames = otherDisruptionRows.flatMap((row) =>
    framesForLine(row, {
      phase: "disruptions",
      heading: "Service disruptions",
      headingLineIds: disruptionHeadingIds,
      bodyTiles: 0,
      charsPerTile,
    })
  )

  const allDisruptionFrames = [...disruptionFrames, ...otherDisruptionFrames]

  const goodFrames = goodServiceBodyFrames(goodDetail, {
    disruptionLineIds: disruptionHeadingIds,
    bodyTiles,
  })

  if (allDisruptionFrames.length === 0) return goodFrames
  if (goodFrames.length === 0) return allDisruptionFrames
  return [...allDisruptionFrames, ...goodFrames]
}

/**
 * Horizontal strip region allocation. Two units keep identity + reason.
 * Four or more units add both summary regions.
 */
/** Keep the active line visible when the title tile cannot show every chip. */
export const visibleHeadingChips = (
  lineIds: readonly string[],
  activeLineId: string | undefined,
  max = 4
): string[] => {
  if (lineIds.length <= max) return [...lineIds]
  if (!activeLineId) return lineIds.slice(0, max)
  const index = lineIds.indexOf(activeLineId)
  if (index < 0) return lineIds.slice(0, max)
  const start = Math.max(0, Math.min(index, lineIds.length - max))
  return lineIds.slice(start, start + max)
}

export const allocateStatusStripRegions = (
  units: number
): StatusStripAllocation => {
  const count = Math.max(1, Math.floor(units))
  if (count <= 2) {
    return {
      showDisruptedSummary: false,
      showOtherSummary: false,
      reasonUnits: count,
    }
  }
  if (count === 3) {
    return {
      showDisruptedSummary: true,
      showOtherSummary: false,
      reasonUnits: 2,
    }
  }
  return {
    showDisruptedSummary: true,
    showOtherSummary: true,
    reasonUnits: count - 2,
  }
}

import {
  getStatusKind,
  getWorstCurrentStatus,
  sortLinesBySeverityAndOrder,
  type StatusKind,
} from "tfl-ts"
import {
  prepareLineAnnouncements,
  type LineAnnouncement,
  type PrepareLineAnnouncementsOptions,
} from "@/lib/tfl/status-reason"
import type { StatusLine } from "@/lib/tfl/status-types"

export type StatusBoardLine = {
  line: StatusLine
  announcements: readonly LineAnnouncement[]
  kind: StatusKind
}

export type StatusBoardSections = {
  /** Incidents, planned engineering, then timetable-closed (tfl-ts kind order). */
  disruptions: StatusBoardLine[]
  /** Running normally. Access / information notices stay here. */
  goodService: StatusBoardLine[]
}

const sectionForKind = (kind: StatusKind): keyof StatusBoardSections => {
  if (kind === "good" || kind === "info") return "goodService"
  return "disruptions"
}

const announcementKind = (announcement: LineAnnouncement): StatusKind =>
  getStatusKind({
    statusSeverity: announcement.statusSeverity,
    statusSeverityDescription: announcement.statusSeverityDescription,
    disruption: announcement.disruption,
  })

const announcementsForSection = (
  section: keyof StatusBoardSections,
  announcements: readonly LineAnnouncement[]
): readonly LineAnnouncement[] => {
  if (section === "goodService") {
    return announcements.filter(
      (announcement) => announcementKind(announcement) === "info"
    )
  }
  return announcements.filter((announcement) => {
    const kind = announcementKind(announcement)
    return kind !== "good" && kind !== "info"
  })
}

const sortBoardLines = (
  rows: StatusBoardLine[],
  now?: number
): StatusBoardLine[] => {
  if (rows.length <= 1) return rows
  const sorted = sortLinesBySeverityAndOrder(
    rows.map((row) => row.line),
    now !== undefined ? { now } : undefined
  )
  const byKey = new Map(
    rows.map((row) => [row.line.id ?? row.line.name ?? "", row])
  )
  return sorted.flatMap((line) => {
    const key = line.id ?? line.name ?? ""
    const row = byKey.get(key)
    return row ? [row] : []
  })
}

/**
 * Live-board passenger layout. Ranking / “which row is current” stay in tfl-ts.
 * Two sections: disruptions (incident → plannedWork → closed) then good service.
 * Timetable-closed stays in Disruptions, sorted last — not a separate group.
 */
export const partitionStatusBoardLines = (
  lines: readonly StatusLine[],
  options: PrepareLineAnnouncementsOptions = {}
): StatusBoardSections => {
  const buckets: StatusBoardSections = {
    disruptions: [],
    goodService: [],
  }
  const statusNow = options.now !== undefined ? { now: options.now } : undefined

  for (const line of lines) {
    const announcements = prepareLineAnnouncements(line.lineStatuses ?? [], {
      ...options,
      line: options.line ?? { name: line.name, modeName: line.modeName },
    })
    const worst = getWorstCurrentStatus(line.lineStatuses, statusNow)
    const kind = worst ? getStatusKind(worst) : "good"
    const section =
      (options.currentOnly ?? true) && announcements.length === 0
        ? "goodService"
        : sectionForKind(kind)
    buckets[section].push({
      line,
      announcements: announcementsForSection(section, announcements),
      kind,
    })
  }

  return {
    disruptions: sortBoardLines(buckets.disruptions, options.now),
    goodService: sortBoardLines(buckets.goodService, options.now),
  }
}

const lineIdOf = (row: StatusBoardLine): string =>
  row.line.id?.trim() || row.line.name?.trim() || "unknown"

/**
 * Split a already-sorted section into priority vs other without re-sorting.
 * Empty / omitted `priorityLineIds` treats every row as priority.
 */
export const splitByPriority = (
  rows: readonly StatusBoardLine[],
  priorityLineIds: readonly string[] | undefined
): { priority: StatusBoardLine[]; other: StatusBoardLine[] } => {
  if (!priorityLineIds?.length) return { priority: [...rows], other: [] }
  const wanted = new Set(priorityLineIds)
  const priority: StatusBoardLine[] = []
  const other: StatusBoardLine[] = []
  for (const row of rows) {
    ;(wanted.has(lineIdOf(row)) ? priority : other).push(row)
  }
  return { priority, other }
}

import {
  getCurrentLineStatuses,
  getStatusKind,
  getWorstCurrentStatus,
} from "tfl-ts"

export type DisruptionStatus = {
  statusSeverity?: number
  statusSeverityDescription?: string
  reason?: string
  disruption?: {
    category?: string
    categoryDescription?: string
  }
  validityPeriods?: {
    isNow?: boolean
    fromDate?: string
    toDate?: string
  }[]
}

const MODE_REASON_PREFIXES = [
  "London Trams",
  "London Tram",
  "London Overground",
  "Docklands Light Railway",
  "Elizabeth line",
  "Elizabeth Line",
  "DLR",
] as const

const escapeRegExp = (value: string) =>
  value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")

const lineReasonPrefixes = (line?: {
  name?: string
  modeName?: string
}): string[] => {
  const prefixes: string[] = [...MODE_REASON_PREFIXES]
  const name = line?.name?.trim()
  if (name) {
    const andName = name.replace(/&/g, "and")
    const ampName = name.replace(/\band\b/gi, "&")
    prefixes.push(name, andName, ampName)
    prefixes.push(`London ${name}`, `London ${andName}`, `London ${name}s`)
  }
  const modeName = line?.modeName?.trim().replace(/-/g, " ")
  if (modeName) {
    prefixes.push(modeName, `${modeName} line`)
  }
  return prefixes
}

/** Drop TfL mode / line prefixes that repeat the card title. */
export const stripStatusReason = (
  reason: string,
  line?: { name?: string; modeName?: string }
): string => {
  const prefixes = [...new Set(lineReasonPrefixes(line))].sort(
    (a, b) => b.length - a.length
  )
  const pattern = new RegExp(
    `^(?:${prefixes.map(escapeRegExp).join("|")})(?:\\s+LINE)?\\s*:\\s*`,
    "i"
  )
  return reason.trim().replace(pattern, "")
}

/** Planned / part closure that replaces a service people expected (`PlannedWork`). */
export const isScheduledEngineeringWork = (status: DisruptionStatus): boolean =>
  getStatusKind(status) === "plannedWork"

const periodOverlapsNow = (
  period: NonNullable<DisruptionStatus["validityPeriods"]>[number],
  now: number
): boolean => {
  const from = period.fromDate
    ? Date.parse(period.fromDate)
    : Number.NEGATIVE_INFINITY
  const to = period.toDate
    ? Date.parse(period.toDate)
    : Number.POSITIVE_INFINITY
  if (Number.isNaN(from) || Number.isNaN(to)) return true
  return now >= from && now <= to
}

/**
 * Live-board operative row: RealTime, no validity window, or a window that
 * overlaps `now`. Not `validityPeriods[].isNow` — that tracks RealTime, so a
 * tram Part Closure can be in force today with `isNow: false`.
 *
 * Pass `now` from cache `fetchedAt`. Omit it only when there is no clock
 * (fixtures / tests that do not care about windows).
 */
export const isCurrentAnnouncement = (
  status: DisruptionStatus,
  now?: number
): boolean => {
  if (status.disruption?.category === "RealTime") return true
  const periods = status.validityPeriods ?? []
  if (periods.length === 0) return true
  if (now === undefined) return true
  return periods.some((period) => periodOverlapsNow(period, now))
}

/** Drop standing hours copy once a RealTime Service Closed row is on the card. */
const dropHoursNoticeWhenClosed = (
  statuses: readonly DisruptionStatus[]
): DisruptionStatus[] => {
  const hasClosedRealtime = statuses.some(
    (status) =>
      status.disruption?.category === "RealTime" &&
      getStatusKind(status) === "closed"
  )
  if (!hasClosedRealtime) return [...statuses]
  return statuses.filter(
    (status) => status.disruption?.category !== "Information"
  )
}

const selectAnnouncementStatuses = (
  statuses: readonly DisruptionStatus[],
  options: { currentOnly: boolean; now?: number }
): DisruptionStatus[] => {
  if (!options.currentOnly) return [...statuses]
  const current = getCurrentLineStatuses(
    statuses,
    options.now !== undefined ? { now: options.now } : undefined
  )
  return dropHoursNoticeWhenClosed(
    current.filter((status) => isCurrentAnnouncement(status, options.now))
  )
}

export type LineAnnouncement = {
  /** Paragraph to render (prefix-stripped unless rawReason). */
  text: string
  /** Worst severity in the merged group — drives chip colour. */
  statusSeverity?: number
  statusSeverityDescription?: string
  disruption?: DisruptionStatus["disruption"]
  /** How many TfL rows collapsed into this paragraph. */
  sourceCount: number
}

export type PrepareLineAnnouncementsOptions = {
  line?: { name?: string; modeName?: string }
  /**
   * Keep operative rows from `getCurrentLineStatuses` (default true).
   * Not `isNow`. Pass `now` from cache `fetchedAt`.
   */
  currentOnly?: boolean
  /** Collapse equal / contained paragraphs. Default true. */
  dedupe?: boolean
  /** Keep TfL's unstripped `reason` string. Default false. */
  rawReason?: boolean
  /** Clock for validity windows. Same stamp as tfl-ts `{ now: fetchedAt }`. */
  now?: number
}

const normalizeAnnouncementKey = (text: string): string =>
  text.toLowerCase().replace(/\s+/g, " ").trim()

const resolveAnnouncementText = (
  status: DisruptionStatus,
  options: { line?: { name?: string; modeName?: string }; rawReason: boolean }
): string => {
  const reason = status.reason?.trim()
  if (reason) {
    return options.rawReason ? reason : stripStatusReason(reason, options.line)
  }
  return status.statusSeverityDescription?.trim() || "Status update"
}

type DraftAnnouncement = LineAnnouncement & {
  key: string
}

const toStatusLike = (draft: DraftAnnouncement): DisruptionStatus => ({
  statusSeverity: draft.statusSeverity,
  statusSeverityDescription: draft.statusSeverityDescription,
  disruption: draft.disruption,
})

/**
 * Passenger-facing announcement list for one line: current filter → text
 * resolution → containment dedupe. All three steps are opt-out via options.
 */
export const prepareLineAnnouncements = (
  statuses: readonly DisruptionStatus[],
  options: PrepareLineAnnouncementsOptions = {}
): readonly LineAnnouncement[] => {
  const currentOnly = options.currentOnly ?? true
  const dedupe = options.dedupe ?? true
  const rawReason = options.rawReason ?? false
  const statusNow = options.now !== undefined ? { now: options.now } : undefined

  const resolved = selectAnnouncementStatuses(statuses, {
    currentOnly,
    now: options.now,
  }).map((status) => {
    const text = resolveAnnouncementText(status, {
      line: options.line,
      rawReason,
    })
    return {
      text,
      key: normalizeAnnouncementKey(text),
      statusSeverity: status.statusSeverity,
      statusSeverityDescription: status.statusSeverityDescription,
      disruption: status.disruption,
      sourceCount: 1,
    } satisfies DraftAnnouncement
  })

  const toAnnouncement = (draft: DraftAnnouncement): LineAnnouncement => ({
    text: draft.text,
    statusSeverity: draft.statusSeverity,
    statusSeverityDescription: draft.statusSeverityDescription,
    disruption: draft.disruption,
    sourceCount: draft.sourceCount,
  })

  if (!dedupe) {
    return resolved.map(toAnnouncement)
  }

  const kept: DraftAnnouncement[] = []

  for (const item of resolved) {
    const matchIndex = kept.findIndex(
      (existing) =>
        existing.key === item.key ||
        existing.key.includes(item.key) ||
        item.key.includes(existing.key)
    )

    if (matchIndex === -1) {
      kept.push(item)
      continue
    }

    const existing = kept[matchIndex]!
    const itemLike = toStatusLike(item)
    const existingLike = toStatusLike(existing)
    const preferIncoming =
      item.key.length > existing.key.length ||
      (item.key.length === existing.key.length &&
        getWorstCurrentStatus([itemLike, existingLike], statusNow) === itemLike)

    const winner = preferIncoming ? item : existing
    const loser = preferIncoming ? existing : item
    const winnerLike = preferIncoming ? itemLike : existingLike
    const loserLike = preferIncoming ? existingLike : itemLike
    const worst =
      getWorstCurrentStatus([winnerLike, loserLike], statusNow) ?? winnerLike

    kept[matchIndex] = {
      text: winner.text,
      key: winner.key,
      statusSeverity: worst.statusSeverity,
      statusSeverityDescription: worst.statusSeverityDescription,
      disruption: worst.disruption,
      sourceCount: winner.sourceCount + loser.sourceCount,
    }
  }

  return kept.map(toAnnouncement)
}

/**
 * Pure unattended frame controller. Callers inject `nowMs`.
 * Pass `startDelayMs` so panels on one board do not advance together.
 */

export const UNATTENDED_DEFAULT_DWELL_MS = 10_000

export type DisplayBehaviour = "interactive" | "unattended"

export type UnattendedPauseReason = "focus" | "hidden"

export const isDocumentHidden = (
  visibilityState: DocumentVisibilityState
): boolean => visibilityState === "hidden"

export type UnattendedSequenceState = {
  index: number
  itemId: string | null
  elapsedMs: number
  lastTickMs: number
  remainingStartDelayMs: number
}

export type TickUnattendedSequenceOptions = {
  itemIds: readonly string[]
  nowMs: number
  dwellMs?: number
  pauseReasons?: readonly UnattendedPauseReason[]
}

export const createUnattendedSequence = (options: {
  itemIds: readonly string[]
  nowMs: number
  startDelayMs?: number
}): UnattendedSequenceState => {
  const itemId = options.itemIds[0] ?? null
  return {
    index: 0,
    itemId,
    elapsedMs: 0,
    lastTickMs: options.nowMs,
    remainingStartDelayMs: Math.max(0, options.startDelayMs ?? 0),
  }
}

const nearestIndex = (previousIndex: number, itemCount: number): number => {
  if (itemCount <= 0) return 0
  if (previousIndex < itemCount) return previousIndex
  return itemCount - 1
}

/**
 * Keep the current item when it still exists (even if the list reordered).
 * When it disappears, move to the nearest remaining index.
 */
export const reconcileUnattendedSequence = (
  state: UnattendedSequenceState,
  nextItemIds: readonly string[]
): UnattendedSequenceState => {
  if (nextItemIds.length === 0) {
    return { ...state, index: 0, itemId: null, elapsedMs: 0 }
  }
  if (state.itemId) {
    const kept = nextItemIds.indexOf(state.itemId)
    if (kept >= 0) {
      return { ...state, index: kept, itemId: nextItemIds[kept] ?? null }
    }
  }
  const index = nearestIndex(state.index, nextItemIds.length)
  return {
    ...state,
    index,
    itemId: nextItemIds[index] ?? null,
    elapsedMs: 0,
  }
}

const isPaused = (
  reasons: readonly UnattendedPauseReason[] | undefined
): boolean => Boolean(reasons && reasons.length > 0)

/** 0–1 through the current dwell. Stays 0 for one frame or during start delay. */
export const unattendedDwellProgress = (
  state: UnattendedSequenceState,
  options: { dwellMs?: number; itemCount: number }
): number => {
  if (options.itemCount <= 1) return 0
  if (state.remainingStartDelayMs > 0) return 0
  const dwellMs = Math.max(1, options.dwellMs ?? UNATTENDED_DEFAULT_DWELL_MS)
  return Math.min(1, state.elapsedMs / dwellMs)
}

/** Advance elapsed time. Pause reasons freeze the current frame. */
export const tickUnattendedSequence = (
  state: UnattendedSequenceState,
  options: TickUnattendedSequenceOptions
): UnattendedSequenceState => {
  const reconciled = reconcileUnattendedSequence(state, options.itemIds)
  const deltaMs = Math.max(0, options.nowMs - reconciled.lastTickMs)
  const hidden = options.pauseReasons?.includes("hidden") ?? false

  if (options.itemIds.length <= 1) {
    return {
      ...reconciled,
      index: 0,
      itemId: options.itemIds[0] ?? null,
      elapsedMs: 0,
      lastTickMs: options.nowMs,
    }
  }

  if (hidden || isPaused(options.pauseReasons)) {
    return { ...reconciled, lastTickMs: options.nowMs }
  }

  let remainingStartDelayMs = reconciled.remainingStartDelayMs
  let elapsedMs = reconciled.elapsedMs
  let index = reconciled.index

  if (remainingStartDelayMs > 0) {
    if (deltaMs < remainingStartDelayMs) {
      return {
        ...reconciled,
        remainingStartDelayMs: remainingStartDelayMs - deltaMs,
        lastTickMs: options.nowMs,
      }
    }
    const leftover = deltaMs - remainingStartDelayMs
    remainingStartDelayMs = 0
    elapsedMs += leftover
  } else {
    elapsedMs += deltaMs
  }

  const dwellMs = Math.max(1, options.dwellMs ?? UNATTENDED_DEFAULT_DWELL_MS)
  const itemCount = options.itemIds.length
  while (elapsedMs >= dwellMs && itemCount > 0) {
    elapsedMs -= dwellMs
    index = (index + 1) % itemCount
  }

  return {
    index,
    itemId: options.itemIds[index] ?? null,
    elapsedMs,
    lastTickMs: options.nowMs,
    remainingStartDelayMs,
  }
}

/**
 * After a hidden document becomes visible again, restart the current frame
 * so the reader gets a full dwell.
 */
export const resumeUnattendedSequence = (
  state: UnattendedSequenceState,
  nowMs: number
): UnattendedSequenceState => ({
  ...state,
  elapsedMs: 0,
  lastTickMs: nowMs,
})

const SENTENCE_SPLIT = /(?<=[.!?])\s+/

/**
 * Split long copy at sentence boundaries. If one sentence still exceeds
 * `maxChars`, fall back to word wraps. Empty input yields no frames.
 */
export const splitTextFrames = (text: string, maxChars: number): string[] => {
  const trimmed = text.trim()
  if (!trimmed) return []
  if (maxChars <= 0 || trimmed.length <= maxChars) return [trimmed]

  const sentences = trimmed.split(SENTENCE_SPLIT).filter(Boolean)
  const frames: string[] = []
  let current = ""

  const flush = () => {
    const piece = current.trim()
    if (piece) frames.push(piece)
    current = ""
  }

  const pushWords = (sentence: string) => {
    for (const word of sentence.split(/\s+/).filter(Boolean)) {
      const next = current ? `${current} ${word}` : word
      if (next.length > maxChars && current) {
        flush()
        current = word
      } else {
        current = next
      }
    }
  }

  for (const sentence of sentences) {
    const next = current ? `${current} ${sentence}` : sentence
    if (next.length <= maxChars) {
      current = next
      continue
    }
    if (current) flush()
    if (sentence.length <= maxChars) {
      current = sentence
      continue
    }
    pushWords(sentence)
  }
  flush()
  return frames.length > 0 ? frames : [trimmed]
}

"use client"

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type FocusEventHandler,
} from "react"
import {
  UNATTENDED_DEFAULT_DWELL_MS,
  createUnattendedSequence,
  isDocumentHidden,
  reconcileUnattendedSequence,
  resumeUnattendedSequence,
  tickUnattendedSequence,
  unattendedDwellProgress,
  type UnattendedPauseReason,
} from "@/lib/tfl/unattended-sequence"

export type UseUnattendedSequenceOptions = {
  itemIds: readonly string[]
  dwellMs?: number
  /** Stagger this panel against others on the same board. */
  startDelayMs?: number
  enabled?: boolean
}

export type UseUnattendedSequenceResult = {
  index: number
  itemId: string | null
  progress: number
  started: boolean
  pauseReasons: readonly UnattendedPauseReason[]
  handleFocus: FocusEventHandler<HTMLElement>
  handleBlur: FocusEventHandler<HTMLElement>
}

const idsKey = (ids: readonly string[]) => ids.join("\0")

/** Reduced motion does not pause the sequence — paint stays instant. */
export const useUnattendedSequence = ({
  itemIds,
  dwellMs = UNATTENDED_DEFAULT_DWELL_MS,
  startDelayMs = 0,
  enabled = true,
}: UseUnattendedSequenceOptions): UseUnattendedSequenceResult => {
  const itemKey = idsKey(itemIds)

  const [index, setIndex] = useState(0)
  const [itemId, setItemId] = useState<string | null>(itemIds[0] ?? null)
  const [progress, setProgress] = useState(0)
  const [started, setStarted] = useState(startDelayMs <= 0)
  const [focused, setFocused] = useState(false)
  const [hidden, setHidden] = useState(false)

  const stateRef = useRef(
    createUnattendedSequence({
      itemIds,
      nowMs: 0,
      startDelayMs,
    })
  )
  const itemIdsRef = useRef(itemIds)

  useEffect(() => {
    itemIdsRef.current = itemIds
  }, [itemIds])

  useEffect(() => {
    if (!enabled) return
    stateRef.current = createUnattendedSequence({
      itemIds: itemIdsRef.current,
      nowMs: Date.now(),
      startDelayMs,
    })
    const next = stateRef.current
    setIndex(next.index)
    setItemId(next.itemId)
    setStarted(next.remainingStartDelayMs <= 0)
    setProgress(
      unattendedDwellProgress(next, {
        dwellMs,
        itemCount: itemIdsRef.current.length,
      })
    )
  }, [dwellMs, enabled, startDelayMs])

  useEffect(() => {
    if (!enabled) return
    const next = reconcileUnattendedSequence(stateRef.current, itemIds)
    stateRef.current = next
    setIndex(next.index)
    setItemId(next.itemId)
    setStarted(next.remainingStartDelayMs <= 0)
    setProgress(
      unattendedDwellProgress(next, { dwellMs, itemCount: itemIds.length })
    )
  }, [dwellMs, enabled, itemKey, itemIds])

  useEffect(() => {
    if (!enabled) return

    const syncHidden = () => {
      const nextHidden = isDocumentHidden(document.visibilityState)
      setHidden((current) => {
        if (current && !nextHidden) {
          stateRef.current = resumeUnattendedSequence(
            stateRef.current,
            Date.now()
          )
          const next = stateRef.current
          setIndex(next.index)
          setItemId(next.itemId)
          setStarted(next.remainingStartDelayMs <= 0)
          setProgress(
            unattendedDwellProgress(next, {
              dwellMs,
              itemCount: itemIdsRef.current.length,
            })
          )
        }
        return nextHidden
      })
    }

    syncHidden()
    document.addEventListener("visibilitychange", syncHidden)
    return () => document.removeEventListener("visibilitychange", syncHidden)
  }, [dwellMs, enabled])

  useEffect(() => {
    if (!enabled || itemIds.length <= 1) return

    const tick = () => {
      const pauseReasons: UnattendedPauseReason[] = []
      if (focused) pauseReasons.push("focus")
      if (hidden) pauseReasons.push("hidden")
      const next = tickUnattendedSequence(stateRef.current, {
        itemIds: itemIdsRef.current,
        nowMs: Date.now(),
        dwellMs,
        pauseReasons,
      })
      stateRef.current = next
      setIndex(next.index)
      setItemId(next.itemId)
      setStarted(next.remainingStartDelayMs <= 0)
      setProgress(
        unattendedDwellProgress(next, {
          dwellMs,
          itemCount: itemIdsRef.current.length,
        })
      )
    }

    const interval = window.setInterval(tick, 250)
    return () => window.clearInterval(interval)
  }, [dwellMs, enabled, focused, hidden, itemIds.length])

  const handleFocus = useCallback<FocusEventHandler<HTMLElement>>(() => {
    setFocused(true)
  }, [])
  const handleBlur = useCallback<FocusEventHandler<HTMLElement>>((event) => {
    const next = event.relatedTarget
    if (next instanceof Node && event.currentTarget.contains(next)) return
    setFocused(false)
  }, [])

  const pauseReasons = useMemo(() => {
    const reasons: UnattendedPauseReason[] = []
    if (focused) reasons.push("focus")
    if (hidden) reasons.push("hidden")
    return reasons
  }, [focused, hidden])

  return {
    index,
    itemId,
    progress,
    started,
    pauseReasons,
    handleFocus,
    handleBlur,
  }
}

"use client"

import { useEffect, useState } from "react"

const QUERY = "(prefers-reduced-motion: reduce)"

/**
 * Always starts `false` on the server and the first client render so SSR
 * HTML matches hydration. The real preference is applied in an effect.
 */
export const usePrefersReducedMotion = (): boolean => {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const mql = window.matchMedia(QUERY)
    const handleChange = () => {
      setReduced(mql.matches)
    }
    handleChange()
    mql.addEventListener("change", handleChange)
    return () => mql.removeEventListener("change", handleChange)
  }, [])

  return reduced
}
